//! Emit the per-topic XCDR2 CDR chains + the battery canonical->CDR view bindings — the CDR twin of
//! [`crate::emit_fields`] (chains) and [`crate::emit_encoders`] (bindings).
//!
//! Two `@generated` files come out of here:
//! * `crates/lib-tms/src/generated_cdr.rs` — for every struct in the `[subset] cdr_topics`
//!   transitive closure, a `pub mod <snake>_cdr` holding a `<T>CdrSrc` accessor trait (UNSCALED
//!   primitive value shape — real `u16`/`i16`/`f32`/… types, not JSON's `i64`/`FloatVal`), a
//!   forwarding impl for `&S`, an uninhabited [`crate::fields::Absent`] impl, an IDENTITY impl for
//!   the concrete `crate::generated::<T>`, one [`crate::cdr::CdrField`] ZST per member (ORDER =
//!   declaration index), the `CdrChain`/`KeyChain` node lists, and `emit_delimited`/`emit_key`
//!   wrappers — plus a `HasCdrChain` impl per concrete type.
//! * `crates/lib-mapping/src/wire/generated_cdr_encoders.rs` — the canonical->CDR view bindings for
//!   the BATTERY subset (Dc/PowerHardware/ActiveDiagnostic), values UNSCALED (`voltage_cv as f32 /
//!   100.0`, current sign conventions identical to the JSON bindings). The inverter/storage CDR
//!   bindings are HAND-WRITTEN (`wire/inverter_cdr/`, `wire/storage_cdr/`), exactly as the JSON side
//!   splits generated battery bindings from hand-written inverter/storage ones.
//!
//! XCDR2 wire mechanics live in the hand-written `lib-tms::cdr` core (DHEADER/optional/encapsulation/
//! sequence helpers, spec-pinned in `cdr/mod.rs`); this emitter only wires the generated member
//! chains into that core. Enums emit via `enum_u32(ordinal)` — every generated enum is `#[repr(u8)]`
//! with implicit discriminants, so the ordinal is `value as u32`.

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::quote;

use crate::emit_fields::chain_closure;
use crate::emit_types;
use crate::model::{Model, RField, RFieldType, RKind, RType};
use crate::overrides::Overrides;

// ==================================================================================================
// generated_cdr.rs  (lib-tms) — the chains
// ==================================================================================================

/// Assemble the `lib-tms` `@generated` CDR chains file for the `[subset] cdr_topics` closure.
pub fn emit_cdr(model: &Model, overrides: &Overrides) -> Result<String, String> {
    let roots = &overrides.subset.cdr_topics;
    if roots.is_empty() {
        return Err("manifest [subset] cdr_topics is empty".into());
    }
    let colliding = emit_types::colliding_names(model);
    let closure = chain_closure(model, roots)?;

    let mut modules = Vec::new();
    let mut has_cdr_chain = Vec::new();
    for t in model.types.iter().filter(|t| {
        t.kind == RKind::Struct
            && closure.contains(&emit_types::rust_type_name(&t.module, &t.name, &colliding))
    }) {
        let rn = emit_types::rust_type_name(&t.module, &t.name, &colliding);
        modules.push(emit_module(model, t, &rn)?);
        let modid = mod_ident(&rn);
        let tid = Ident::new(&rn, Span::call_site());
        has_cdr_chain.push(quote! {
            impl crate::cdr::HasCdrChain for crate::generated::#tid {
                type CdrChain = #modid::CdrChain;
            }
        });
    }

    let items = quote! {
        #(#modules)*
        #(#has_cdr_chain)*
    };

    let file =
        syn::parse2::<syn::File>(items).map_err(|e| format!("emitted CDR chains invalid: {e}"))?;
    let formatted = prettyplease::unparse(&file);
    Ok(format!(
        "// @generated by tms-idl-codegen — DO NOT EDIT.\n\
         //! Generated per-topic XCDR2 CDR chains — one `<snake>_cdr` module per struct in the\n\
         //! `tms-overrides.toml` `[subset] cdr_topics` transitive closure: the `<T>CdrSrc` accessor\n\
         //! trait (UNSCALED primitive value shape, IDL order), the `&S` forwarding impl, the\n\
         //! `Absent` impl, the identity impl for the concrete generated type, one ZST `CdrField` per\n\
         //! member, the `CdrChain`/`KeyChain` node lists, `emit_delimited`/`emit_key` wrappers, and a\n\
         //! `HasCdrChain` impl per concrete type.\n\
         //!\n\
         //! Source: `docs/compliance/tms/mil-std-3071_data_model.idl` (MIL-STD-3071 TMS 2.0.2) +\n\
         //! `tms-overrides.toml` (the `cdr_topics` subset). Regenerate with `just tms-codegen`;\n\
         //! `just tms-codegen-check` fails if this file is stale.\n\
         //!\n\
         //! Wire mechanics (DHEADER nesting, optional presence-flag, alignment, enum width, string\n\
         //! NUL, primitive-vs-appendable sequences) are the spec-pinned `lib_tms::cdr` core; this\n\
         //! file only orders each type's members into a `CdrChain` and routes each through the core.\n\
         #![allow(clippy::all)]\n\
         #![allow(rustdoc::all)]\n\
         #![cfg_attr(rustfmt, rustfmt::skip)]\n\n{formatted}"
    ))
}

// ---- naming (duplicated from emit_fields so this emitter is self-contained) -----------------------

fn to_snake(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(s.len() + 4);
    for (i, &c) in chars.iter().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 && (chars[i - 1].is_ascii_lowercase() || chars[i - 1].is_ascii_digit()) {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn pascal(s: &str) -> String {
    let mut out = String::new();
    for seg in s.split('_') {
        let mut ch = seg.chars();
        if let Some(f) = ch.next() {
            out.push(f.to_ascii_uppercase());
            out.extend(ch.map(|c| c.to_ascii_lowercase()));
        }
    }
    out
}

fn mod_ident(rust_name: &str) -> Ident {
    Ident::new(&format!("{}_cdr", to_snake(rust_name)), Span::call_site())
}

fn src_trait_ident(rust_name: &str) -> Ident {
    Ident::new(&format!("{rust_name}CdrSrc"), Span::call_site())
}

fn safe_ident(s: &str) -> Ident {
    match syn::parse_str::<Ident>(s) {
        Ok(id) => id,
        Err(_) => Ident::new_raw(s, Span::call_site()),
    }
}

/// The Rust type name a resolved `Ref` points at (mirrors `emit_fields::ref_rust_name`).
fn ref_rust_name(refstr: &str) -> String {
    match refstr.rsplit_once("::") {
        Some((leaf, simple)) => {
            let mut c = leaf.chars();
            let cap = match c.next() {
                Some(f) => f.to_ascii_uppercase().to_string() + c.as_str(),
                None => String::new(),
            };
            format!("{cap}{simple}")
        }
        None => refstr.to_string(),
    }
}

fn find_ref<'a>(model: &'a Model, refstr: &str) -> Option<&'a RType> {
    match refstr.rsplit_once("::") {
        Some((leaf, simple)) => model
            .types
            .iter()
            .find(|t| t.name == simple && module_leaf(&t.module) == leaf),
        None => model.types.iter().find(|t| t.name == refstr),
    }
}

fn module_leaf(module: &str) -> &str {
    module.rsplit("::").next().unwrap_or(module)
}

// ---- field classification ------------------------------------------------------------------------

/// A field's XCDR2 accessor/emit shape. `Enum`/`Struct` carry the referenced type's RUST name.
enum Kind {
    Str,
    Prim(PrimKind),
    Bool,
    F32,
    F64,
    Enum(String),
    Struct(String),
    SeqStruct(String),
    SeqEnum(String),
    SeqStr(u32),
    SeqF32,
    SeqF64,
    SeqBool,
    SeqPrim(PrimKind),
}

/// An integer primitive width (drives both the accessor return type and the `CdrSink` method).
#[derive(Clone, Copy)]
enum PrimKind {
    U8,
    U16,
    U32,
    U64,
    I16,
    I32,
}

impl PrimKind {
    fn ty(self) -> TokenStream {
        match self {
            PrimKind::U8 => quote!(u8),
            PrimKind::U16 => quote!(u16),
            PrimKind::U32 => quote!(u32),
            PrimKind::U64 => quote!(u64),
            PrimKind::I16 => quote!(i16),
            PrimKind::I32 => quote!(i32),
        }
    }
    /// The `CdrSink` method that emits this primitive.
    fn sink_method(self) -> Ident {
        let m = match self {
            PrimKind::U8 => "u8",
            PrimKind::U16 => "u16",
            PrimKind::U32 => "u32",
            PrimKind::U64 => "u64",
            PrimKind::I16 => "i16",
            PrimKind::I32 => "i32",
        };
        Ident::new(m, Span::call_site())
    }
}

fn prim_kind(ty: &RFieldType) -> Option<PrimKind> {
    Some(match ty {
        RFieldType::U8 => PrimKind::U8,
        RFieldType::U16 => PrimKind::U16,
        RFieldType::U32 => PrimKind::U32,
        RFieldType::U64 => PrimKind::U64,
        RFieldType::I16 => PrimKind::I16,
        RFieldType::I32 => PrimKind::I32,
        _ => return None,
    })
}

fn classify(model: &Model, ty: &RFieldType) -> Result<Kind, String> {
    Ok(match ty {
        RFieldType::Str(_) => Kind::Str,
        RFieldType::F32 => Kind::F32,
        RFieldType::F64 => Kind::F64,
        RFieldType::Bool => Kind::Bool,
        RFieldType::U8
        | RFieldType::U16
        | RFieldType::U32
        | RFieldType::U64
        | RFieldType::I16
        | RFieldType::I32 => Kind::Prim(prim_kind(ty).expect("prim")),
        RFieldType::Ref(r) => {
            let t = find_ref(model, r).ok_or_else(|| format!("unresolved ref `{r}`"))?;
            match t.kind {
                RKind::Enum => Kind::Enum(ref_rust_name(r)),
                RKind::Struct => Kind::Struct(ref_rust_name(r)),
            }
        }
        RFieldType::Seq(elem, _) => match &**elem {
            RFieldType::Str(n) => Kind::SeqStr(*n),
            RFieldType::F32 => Kind::SeqF32,
            RFieldType::F64 => Kind::SeqF64,
            RFieldType::Bool => Kind::SeqBool,
            RFieldType::Ref(r) => {
                let t = find_ref(model, r).ok_or_else(|| format!("unresolved ref `{r}`"))?;
                match t.kind {
                    RKind::Enum => Kind::SeqEnum(ref_rust_name(r)),
                    RKind::Struct => Kind::SeqStruct(ref_rust_name(r)),
                }
            }
            RFieldType::Seq(..) => {
                return Err("sequence-of-sequence unsupported by CDR chain emitter".into())
            }
            other => Kind::SeqPrim(prim_kind(other).ok_or("unsupported sequence element type")?),
        },
    })
}

fn is_seq(kind: &Kind) -> bool {
    matches!(
        kind,
        Kind::SeqStruct(_)
            | Kind::SeqEnum(_)
            | Kind::SeqStr(_)
            | Kind::SeqF32
            | Kind::SeqF64
            | Kind::SeqBool
            | Kind::SeqPrim(_)
    )
}

// ---- per-struct module ---------------------------------------------------------------------------

struct FieldGen {
    trait_decl: TokenStream,
    fwd: TokenStream,
    absent: TokenStream,
    identity: TokenStream,
    zst: TokenStream,
    zst_ident: Ident,
    is_key: bool,
}

fn emit_module(model: &Model, t: &RType, rust_name: &str) -> Result<TokenStream, String> {
    let modid = mod_ident(rust_name);
    let src_trait = src_trait_ident(rust_name);
    let concrete = Ident::new(rust_name, Span::call_site());
    let doc = format!(
        "XCDR2 CDR chain for `{}::{}` — {}:{}",
        t.module, t.name, "mil-std-3071_data_model.idl", t.idl_line
    );

    let mut gens = Vec::new();
    for (i, f) in t.fields.iter().enumerate() {
        gens.push(emit_field(model, t, f, i, &src_trait)?);
    }

    let trait_decls = gens.iter().map(|g| &g.trait_decl);
    let fwds = gens.iter().map(|g| &g.fwd);
    let absents = gens.iter().map(|g| &g.absent);
    let identities = gens.iter().map(|g| &g.identity);
    let zsts = gens.iter().map(|g| &g.zst);

    // CdrChain = CdrNode<F0, CdrNode<F1, ... CdrNil>>, folded from the back (IDL order preserved).
    let mut chain = quote!(CdrNil);
    for g in gens.iter().rev() {
        let z = &g.zst_ident;
        chain = quote!(CdrNode<#z, #chain>);
    }

    // KeyChain = the same ZSTs but only the `@key` members, in declaration order (KeyHash plumbing;
    // WP4 completes the big-endian/MD5 wrapping — see cdr::emit_key).
    let mut key_chain = quote!(CdrNil);
    for g in gens.iter().rev().filter(|g| g.is_key) {
        let z = &g.zst_ident;
        key_chain = quote!(CdrNode<#z, #key_chain>);
    }

    Ok(quote! {
        #[doc = #doc]
        pub mod #modid {
            use crate::cdr::*;

            /// Accessor view of the topic payload with UNSCALED primitive types — implemented by the
            /// concrete generated struct (identity) and by any borrowed canonical binding.
            pub trait #src_trait {
                #(#trait_decls)*
            }

            impl<'r, S: #src_trait + ?Sized> #src_trait for &'r S {
                #(#fwds)*
            }

            impl #src_trait for crate::fields::Absent {
                #(#absents)*
            }

            impl #src_trait for crate::generated::#concrete {
                #(#identities)*
            }

            #(#zsts)*

            /// The type-level member list, in IDL declaration order.
            pub type CdrChain = #chain;

            /// The `@key`-member list (declaration order) for KeyHash construction; `CdrNil` if the
            /// type declares no key.
            pub type KeyChain = #key_chain;

            /// Emit this type as a nested APPENDABLE member/element: a DHEADER over its members
            /// (DDS-XTypes 1.3 rule (30)). Called by an enclosing type's field/element emit.
            #[inline(always)]
            pub fn emit_delimited<S: CdrSink, Src: #src_trait + ?Sized>(src: &Src, sink: &mut S) {
                crate::cdr::emit_dheader::<Src, CdrChain, S>(src, sink);
            }

            /// Serialize this type's `@key` members in declaration order (KeyHash plumbing — no
            /// encapsulation header, no enclosing DHEADER; see `crate::cdr::emit_key`).
            #[inline(always)]
            pub fn emit_key<S: CdrSink, Src: #src_trait + ?Sized>(src: &Src, sink: &mut S) {
                crate::cdr::emit_key::<Src, KeyChain, S>(src, sink);
            }
        }
    })
}

fn emit_field(
    model: &Model,
    t: &RType,
    f: &RField,
    index: usize,
    src_trait: &Ident,
) -> Result<FieldGen, String> {
    let kind = classify(model, &f.ty).map_err(|e| format!("{}.{}: {e}", t.name, f.idl_name))?;
    let m = safe_ident(&f.name);
    let has_m = safe_ident(&format!("has_{}", f.name));
    let field_pascal = pascal(&f.name);
    let zst_ident = Ident::new(&format!("{field_pascal}Field"), Span::call_site());
    let order = Literal::u16_unsuffixed(index as u16);
    let opt = f.optional;

    // Scalar accessor return type (None for the GAT/RPITIT struct shapes, handled below).
    let scalar_ret: Option<TokenStream> = match &kind {
        Kind::Str => Some(quote!(&str)),
        Kind::Prim(p) => Some(p.ty()),
        Kind::Bool => Some(quote!(bool)),
        Kind::F32 => Some(quote!(f32)),
        Kind::F64 => Some(quote!(f64)),
        Kind::Enum(e) => {
            let eid = Ident::new(e, Span::call_site());
            Some(quote!(crate::generated::#eid))
        }
        Kind::SeqStr(n) => {
            let n = Literal::usize_unsuffixed(*n as usize);
            Some(quote!(&[heapless::String<#n>]))
        }
        Kind::SeqF32 => Some(quote!(&[f32])),
        Kind::SeqF64 => Some(quote!(&[f64])),
        Kind::SeqBool => Some(quote!(&[bool])),
        Kind::SeqPrim(p) => {
            let e = p.ty();
            Some(quote!(&[#e]))
        }
        Kind::SeqEnum(e) => {
            let eid = Ident::new(e, Span::call_site());
            Some(quote!(&[crate::generated::#eid]))
        }
        Kind::Struct(_) | Kind::SeqStruct(_) => None,
    };

    // --- accessor trait / forwarding / Absent / identity, by shape ---
    let (trait_decl, fwd, absent, identity) = match &kind {
        Kind::Struct(n) => {
            let gat = Ident::new(&field_pascal, Span::call_site());
            let nmod = mod_ident(n);
            let nsrc = src_trait_ident(n);
            let nid = Ident::new(n, Span::call_site());
            if opt {
                (
                    quote! {
                        type #gat<'a>: super::#nmod::#nsrc where Self: 'a;
                        fn #m(&self) -> Option<Self::#gat<'_>>;
                    },
                    quote! {
                        type #gat<'a> = S::#gat<'a> where Self: 'a;
                        fn #m(&self) -> Option<Self::#gat<'_>> { (**self).#m() }
                    },
                    quote! {
                        type #gat<'a> = crate::fields::Absent where Self: 'a;
                        fn #m(&self) -> Option<Self::#gat<'_>> { match *self {} }
                    },
                    quote! {
                        type #gat<'a> = &'a crate::generated::#nid where Self: 'a;
                        fn #m(&self) -> Option<Self::#gat<'_>> { self.#m.as_ref() }
                    },
                )
            } else {
                (
                    quote! {
                        type #gat<'a>: super::#nmod::#nsrc where Self: 'a;
                        fn #m(&self) -> Self::#gat<'_>;
                    },
                    quote! {
                        type #gat<'a> = S::#gat<'a> where Self: 'a;
                        fn #m(&self) -> Self::#gat<'_> { (**self).#m() }
                    },
                    quote! {
                        type #gat<'a> = crate::fields::Absent where Self: 'a;
                        fn #m(&self) -> Self::#gat<'_> { match *self {} }
                    },
                    quote! {
                        type #gat<'a> = &'a crate::generated::#nid where Self: 'a;
                        fn #m(&self) -> Self::#gat<'_> { &self.#m }
                    },
                )
            }
        }
        Kind::SeqStruct(e) => {
            let gat = Ident::new(&format!("{field_pascal}Item"), Span::call_site());
            let emod = mod_ident(e);
            let esrc = src_trait_ident(e);
            let eid = Ident::new(e, Span::call_site());
            let has_decl = if opt { quote! { fn #has_m(&self) -> bool; } } else { quote! {} };
            let has_fwd = if opt {
                quote! { fn #has_m(&self) -> bool { (**self).#has_m() } }
            } else {
                quote! {}
            };
            let has_absent = if opt {
                quote! { fn #has_m(&self) -> bool { match *self {} } }
            } else {
                quote! {}
            };
            let (has_identity, iter_identity) = if opt {
                (
                    quote! { fn #has_m(&self) -> bool { self.#m.is_some() } },
                    quote! { self.#m.as_deref().unwrap_or(&[]).iter() },
                )
            } else {
                (quote! {}, quote! { self.#m.iter() })
            };
            (
                quote! {
                    type #gat<'a>: super::#emod::#esrc where Self: 'a;
                    #has_decl
                    fn #m(&self) -> impl Iterator<Item = Self::#gat<'_>> + '_;
                },
                quote! {
                    type #gat<'a> = S::#gat<'a> where Self: 'a;
                    #has_fwd
                    fn #m(&self) -> impl Iterator<Item = Self::#gat<'_>> + '_ { (**self).#m() }
                },
                quote! {
                    type #gat<'a> = crate::fields::Absent where Self: 'a;
                    #has_absent
                    fn #m(&self) -> impl Iterator<Item = Self::#gat<'_>> + '_ { core::iter::empty() }
                },
                quote! {
                    type #gat<'a> = &'a crate::generated::#eid where Self: 'a;
                    #has_identity
                    fn #m(&self) -> impl Iterator<Item = Self::#gat<'_>> + '_ { #iter_identity }
                },
            )
        }
        // Scalar-ish shapes (incl. scalar/enum/string sequences, which return slices).
        _ => {
            let ret = scalar_ret.clone().expect("scalar shapes have a return type");
            let seq = is_seq(&kind);
            // Optional SCALARS wrap in Option; optional SEQUENCES keep the slice return (empty when
            // absent) and add `has_x` for the present/absent distinction.
            let ret_full = if opt && !seq { quote!(Option<#ret>) } else { ret.clone() };
            let has_decl = if opt && seq { quote! { fn #has_m(&self) -> bool; } } else { quote! {} };
            let has_fwd = if opt && seq {
                quote! { fn #has_m(&self) -> bool { (**self).#has_m() } }
            } else {
                quote! {}
            };
            let has_absent = if opt && seq {
                quote! { fn #has_m(&self) -> bool { match *self {} } }
            } else {
                quote! {}
            };
            let has_identity = if opt && seq {
                quote! { fn #has_m(&self) -> bool { self.#m.is_some() } }
            } else {
                quote! {}
            };
            let identity_body = identity_scalar_body(&kind, &m, opt);
            (
                quote! {
                    #has_decl
                    fn #m(&self) -> #ret_full;
                },
                quote! {
                    #has_fwd
                    fn #m(&self) -> #ret_full { (**self).#m() }
                },
                quote! {
                    #has_absent
                    fn #m(&self) -> #ret_full { match *self {} }
                },
                quote! {
                    #has_identity
                    fn #m(&self) -> #ret_full { #identity_body }
                },
            )
        }
    };

    // --- CdrField ZST emit body ---
    let emit_body = emit_field_body(&kind, &m, &has_m, opt);

    let zst = quote! {
        pub struct #zst_ident;
        impl<Src: #src_trait + ?Sized> CdrField<Src> for #zst_ident {
            const ORDER: u16 = #order;
            fn emit<S: CdrSink>(src: &Src, sink: &mut S) {
                #emit_body
            }
        }
    };

    Ok(FieldGen {
        trait_decl,
        fwd,
        absent,
        identity,
        zst,
        zst_ident,
        is_key: f.is_key,
    })
}

/// Identity-impl body for the scalar shapes (plain reads off the concrete generated struct, real
/// types — no scaling, no `i64` widening).
fn identity_scalar_body(kind: &Kind, m: &Ident, opt: bool) -> TokenStream {
    match kind {
        Kind::Str => {
            if opt {
                quote! { self.#m.as_deref() }
            } else {
                quote! { self.#m.as_str() }
            }
        }
        // Real numeric/bool/enum: the generated field already has the right type (`Option<T>` when
        // optional), so it reads straight through.
        Kind::Prim(_) | Kind::Bool | Kind::F32 | Kind::F64 | Kind::Enum(_) => quote! { self.#m },
        // Slices: deref-coerce the heapless::Vec (or the Option's deref) to the element slice.
        _ => {
            if opt {
                quote! { self.#m.as_deref().unwrap_or(&[]) }
            } else {
                quote! { &self.#m }
            }
        }
    }
}

/// The `CdrField::emit` body: emit `src.#m()`'s XCDR2 bytes through the sink, routing optionals via
/// `emit_optional`/`emit_optional_seq` (the presence-flag policy points) and nested appendable
/// members/elements via `emit_delimited`.
fn emit_field_body(kind: &Kind, m: &Ident, has_m: &Ident, opt: bool) -> TokenStream {
    if opt {
        if is_seq(kind) {
            let body = seq_present_body(kind, m, quote!(sink));
            return quote! {
                emit_optional_seq(sink, src.#has_m(), |sink| { #body });
            };
        }
        // Optional value member (scalar / enum / string / nested struct): presence flag + value.
        let present = match kind {
            Kind::Str => quote! { sink.string(*v); },
            Kind::Prim(p) => {
                let sm = p.sink_method();
                quote! { sink.#sm(*v); }
            }
            Kind::Bool => quote! { sink.boolean(*v); },
            Kind::F32 => quote! { sink.f32(*v); },
            Kind::F64 => quote! { sink.f64(*v); },
            Kind::Enum(_) => quote! { sink.enum_u32(*v as u32); },
            Kind::Struct(n) => {
                let nmod = mod_ident(n);
                quote! { super::#nmod::emit_delimited(v, sink); }
            }
            _ => unreachable!("optional sequences handled above; no other value shapes"),
        };
        return quote! {
            emit_optional(sink, src.#m().as_ref(), |v, sink| { #present });
        };
    }

    // Required member.
    match kind {
        Kind::Str => quote! { sink.string(src.#m()); },
        Kind::Prim(p) => {
            let sm = p.sink_method();
            quote! { sink.#sm(src.#m()); }
        }
        Kind::Bool => quote! { sink.boolean(src.#m()); },
        Kind::F32 => quote! { sink.f32(src.#m()); },
        Kind::F64 => quote! { sink.f64(src.#m()); },
        Kind::Enum(_) => quote! { sink.enum_u32(src.#m() as u32); },
        Kind::Struct(n) => {
            let nmod = mod_ident(n);
            quote! { super::#nmod::emit_delimited(&src.#m(), sink); }
        }
        _ => seq_present_body(kind, m, quote!(sink)),
    }
}

/// The bytes of a PRESENT sequence value (used both for a required sequence and inside the
/// `emit_optional_seq` present-branch). `sink_expr` is the sink to write into (`sink`).
fn seq_present_body(kind: &Kind, m: &Ident, sink_expr: TokenStream) -> TokenStream {
    match kind {
        // Non-primitive APPENDABLE-struct sequence: DHEADER + count + delimited elements (rules
        // (12)+(30)).
        Kind::SeqStruct(e) => {
            let emod = mod_ident(e);
            quote! {
                crate::cdr::emit_appendable_seq::<_, _, super::#emod::CdrChain, _, _>(
                    #sink_expr, || src.#m()
                );
            }
        }
        // Non-primitive string sequence: DHEADER + count + strings (rule (12), no per-element
        // DHEADER).
        Kind::SeqStr(_) => quote! { crate::cdr::emit_string_seq(#sink_expr, src.#m()); },
        // Primitive-element sequences: count + elements, NO sequence DHEADER (rule (11)). Enums are
        // fixed-width holders, treated primitive-like here (flagged for WP5 arbitration).
        Kind::SeqF32 => seq_prim_loop(m, sink_expr, quote! { sink.f32(*x); }),
        Kind::SeqF64 => seq_prim_loop(m, sink_expr, quote! { sink.f64(*x); }),
        Kind::SeqBool => seq_prim_loop(m, sink_expr, quote! { sink.boolean(*x); }),
        Kind::SeqPrim(p) => {
            let sm = p.sink_method();
            seq_prim_loop(m, sink_expr, quote! { sink.#sm(*x); })
        }
        Kind::SeqEnum(_) => seq_prim_loop(m, sink_expr, quote! { sink.enum_u32(*x as u32); }),
        _ => unreachable!("seq_present_body only handles sequence kinds"),
    }
}

/// A primitive sequence body: `{ length : u32 } << elements*` (no DHEADER). `sink_expr` is rebound
/// to `sink` inside so `per_item` can uniformly say `sink.<m>(*x)`.
fn seq_prim_loop(m: &Ident, sink_expr: TokenStream, per_item: TokenStream) -> TokenStream {
    quote! {
        {
            let sink = #sink_expr;
            let items = src.#m();
            sink.u32(items.len() as u32);
            for x in items {
                #per_item
            }
        }
    }
}

// ==================================================================================================
// generated_cdr_encoders.rs  (lib-mapping) — the battery canonical->CDR view bindings
// ==================================================================================================

/// Assemble the `lib-mapping` `@generated` CDR view-binding file for the BATTERY subset
/// (Dc/PowerHardware/ActiveDiagnostic). Values are UNSCALED (real `f32`), mirroring
/// `emit_encoders::emit_mapping`'s JSON bindings but through the `…CdrSrc` traits. Inverter/storage
/// CDR bindings are HAND-WRITTEN (`wire/inverter_cdr/`, `wire/storage_cdr/`).
pub fn emit_cdr_encoders(model: &Model, _overrides: &Overrides) -> Result<String, String> {
    // Source MAX_DTC from the model (ActiveDiagnosticState.codes bound) so it can't drift.
    let ads = model
        .types
        .iter()
        .find(|t| t.name == "ActiveDiagnosticState" && t.module == "tms")
        .ok_or("model missing tms::ActiveDiagnosticState")?;
    let max_dtc = ads
        .fields
        .iter()
        .find(|f| f.idl_name == "codes")
        .and_then(|f| f.bound)
        .ok_or("ActiveDiagnosticState.codes has no bound")? as usize;
    let max_dtc_lit = Literal::usize_unsuffixed(max_dtc);

    let body = cdr_encoders_body(max_dtc_lit);

    let items = quote! {
        use lib_canonical::{CanonicalFault, CanonicalReading};
        use lib_tms::{ClockMonotonic, Identity};
        use lib_tms::fields::Absent;

        #body
    };

    let file = syn::parse2::<syn::File>(items)
        .map_err(|e| format!("emitted CDR encoders invalid: {e}"))?;
    let formatted = prettyplease::unparse(&file);
    Ok(format!(
        "// @generated by tms-idl-codegen — DO NOT EDIT.\n\
         //! Generated canonical->TMS XCDR2 (CDR) view bindings for the BATTERY subset — the CDR twin\n\
         //! of `generated_encoders.rs`.\n\
         //!\n\
         //! Source: `docs/compliance/tms/mil-std-3071_data_model.idl` (MIL-STD-3071 TMS 2.0.2) +\n\
         //! `tms-overrides.toml`. Regenerate with `just tms-codegen`; `just tms-codegen-check` fails\n\
         //! if this file is stale.\n\
         //!\n\
         //! Each `…CdrView` implements the generated `lib_tms::generated_cdr::…CdrSrc` accessors with\n\
         //! UNSCALED values (`voltage_cv as f32 / 100.0`, current sign conventions identical to the\n\
         //! JSON bindings in `generated_encoders.rs`). `render_cdr` builds these and drives\n\
         //! `emit_object_cdr`. Inverter/storage CDR bindings are hand-written siblings.\n\
         #![allow(clippy::all)]\n\
         #![allow(rustdoc::all)]\n\
         #![cfg_attr(rustfmt, rustfmt::skip)]\n\n{formatted}"
    ))
}

fn cdr_encoders_body(max_dtc_lit: Literal) -> TokenStream {
    let dc = cdr_enc_dc();
    let hw = cdr_enc_power_hardware();
    let ad = cdr_enc_active_diagnostic(max_dtc_lit);
    quote! {
        /// Fault flag getter + J1939 SPN + hint — the value binding for `ActiveDiagnosticState`
        /// (identical table to `generated_encoders::FAULT_TABLE`).
        #[allow(clippy::type_complexity)]
        const FAULT_TABLE: &[(fn(&CanonicalFault) -> bool, u32, &str)] = &[
            (|f| f.high_voltage_protection, 1, "cell overvoltage"),
            (|f| f.low_voltage_protection, 2, "cell undervoltage"),
            (|f| f.high_temperature_charge_protection, 3, "hi-temp charge"),
            (|f| f.low_temperature_charge_protection, 4, "lo-temp charge"),
            (|f| f.charge_overcurrent_protection, 5, "charge overcurrent"),
            (|f| f.discharge_overcurrent_protection, 6, "discharge overcurrent"),
            (|f| f.short_circuit_protection, 7, "short circuit"),
            (|f| f.mosfet_fault, 8, "mosfet fault"),
            (|f| f.cell_balance_warning, 9, "cell imbalance"),
            (|f| f.low_capacity_warning, 10, "low capacity"),
            (|f| f.high_temperature_discharge_warning, 11, "hi-temp discharge"),
            (|f| f.low_temperature_discharge_warning, 12, "lo-temp discharge"),
            (|f| f.low_voltage_warning, 13, "low voltage warn"),
            (|f| f.high_voltage_warning, 14, "high voltage warn"),
            (|f| f.discharge_current_warning, 15, "discharge current"),
            (|f| f.charge_current_warning, 16, "charge current"),
        ];

        /// Round-half-away-from-zero integer division (`denominator > 0`).
        #[allow(clippy::all)]
        fn round_div_i64(numerator: i64, denominator: i64) -> i64 {
            if numerator >= 0 {
                (numerator + denominator / 2) / denominator
            } else {
                -((-numerator + denominator / 2) / denominator)
            }
        }

        #dc
        #hw
        #ad
    }
}

fn cdr_enc_dc() -> TokenStream {
    quote! {
        /// DC power line — voltage (cV -> V), amperage (source-negated cA -> A), power (V×A).
        pub struct DcPowerLineCdrView {
            pub voltage_cv: u16,
            pub current_ca: i16,
        }
        impl lib_tms::generated_cdr::dc_power_line_measurement_cdr::DcPowerLineMeasurementCdrSrc
            for DcPowerLineCdrView
        {
            fn voltage(&self) -> f32 { self.voltage_cv as f32 / 100.0 }
            fn amperage(&self) -> f32 { -(self.current_ca as f32) / 100.0 }
            fn power(&self) -> f32 {
                (self.voltage_cv as f32 / 100.0) * (-(self.current_ca as f32) / 100.0)
            }
        }

        /// DC power port for the battery leg (port 0, one line).
        pub struct DcPowerPortCdrView<'a> {
            pub reading: &'a CanonicalReading,
        }
        impl<'a> lib_tms::generated_cdr::dc_power_port_measurement_cdr::DcPowerPortMeasurementCdrSrc
            for DcPowerPortCdrView<'a>
        {
            fn port_number(&self) -> i32 { 0 }
            type LineItem<'b> = DcPowerLineCdrView where Self: 'b;
            fn line(&self) -> impl Iterator<Item = Self::LineItem<'_>> + '_ {
                core::iter::once(DcPowerLineCdrView {
                    voltage_cv: self.reading.total_voltage_cv,
                    current_ca: self.reading.current_ca,
                })
            }
            // `power_rate_of_change` has no canonical source (NaN in JSON) -> f32::NAN.
            fn power_rate_of_change(&self) -> f32 { f32::NAN }
        }

        /// `DcMeasurementUpdate` battery view.
        pub struct DcMeasurementUpdateCdrView<'a> {
            pub reading: &'a CanonicalReading,
            pub device_id: &'a Identity,
            pub now: &'a ClockMonotonic,
        }
        impl<'a> lib_tms::generated_cdr::dc_measurement_update_cdr::DcMeasurementUpdateCdrSrc
            for DcMeasurementUpdateCdrView<'a>
        {
            fn device_id(&self) -> &str { self.device_id.as_str() }
            type TimeMeasured<'b> = &'b ClockMonotonic where Self: 'b;
            fn time_measured(&self) -> Self::TimeMeasured<'_> { self.now }
            type ExternalMeasurementItem<'b> = DcPowerPortCdrView<'b> where Self: 'b;
            fn external_measurement(
                &self,
            ) -> impl Iterator<Item = Self::ExternalMeasurementItem<'_>> + '_ {
                core::iter::once(DcPowerPortCdrView { reading: self.reading })
            }
            type InternalMeasurementItem<'b> = Absent where Self: 'b;
            fn internal_measurement(
                &self,
            ) -> impl Iterator<Item = Self::InternalMeasurementItem<'_>> + '_ {
                core::iter::empty()
            }
        }
    }
}

fn cdr_enc_power_hardware() -> TokenStream {
    quote! {
        /// One storage cell's CDR view.
        pub struct StorageCellCdrView<'a> {
            pub index: usize,
            pub reading: &'a CanonicalReading,
        }
        impl<'a> lib_tms::generated_cdr::storage_cell_state_cdr::StorageCellStateCdrSrc
            for StorageCellCdrView<'a>
        {
            fn cell_number(&self) -> u16 { self.index as u16 }
            fn cycle_counter(&self) -> f32 { self.reading.cycles as f32 }
            fn state_of_charge(&self) -> Option<f32> {
                Some(self.reading.soc_dpct as f32 / 1000.0)
            }
            fn temperature(&self) -> f32 {
                match self.reading.temperatures_raw.len() {
                    0 => f32::NAN,
                    n => {
                        let raw = self.reading.temperatures_raw[core::cmp::min(self.index, n - 1)] as f32;
                        (raw - 2731.0) / 10.0
                    }
                }
            }
            fn voltage(&self) -> f32 {
                let mv = self.reading.cell_voltages_mv.get(self.index).copied().unwrap_or(0);
                mv as f32 / 1000.0
            }
        }

        /// `EnergyStorageState` CDR view (temperature aggregations + cells).
        pub struct EnergyStorageCdrView<'a> {
            pub reading: &'a CanonicalReading,
        }
        impl<'a> lib_tms::generated_cdr::energy_storage_state_cdr::EnergyStorageStateCdrSrc
            for EnergyStorageCdrView<'a>
        {
            fn min_temperature(&self) -> f32 {
                if self.reading.temperatures_raw.is_empty() {
                    f32::NAN
                } else {
                    let mut min_raw = i64::MAX;
                    for &raw in self.reading.temperatures_raw.iter() {
                        min_raw = min_raw.min(raw as i64);
                    }
                    (min_raw as f32 - 2731.0) / 10.0
                }
            }
            fn average_temperature(&self) -> f32 {
                if self.reading.temperatures_raw.is_empty() {
                    f32::NAN
                } else {
                    let mut sum_raw: i64 = 0;
                    for &raw in self.reading.temperatures_raw.iter() {
                        sum_raw += raw as i64;
                    }
                    let n = self.reading.temperatures_raw.len() as i64;
                    let numerator_tenths_x1000 = (sum_raw - 2731 * n) * 1000;
                    let avg_milli = round_div_i64(numerator_tenths_x1000, n * 10);
                    avg_milli as f32 / 1000.0
                }
            }
            fn max_temperature(&self) -> f32 {
                if self.reading.temperatures_raw.is_empty() {
                    f32::NAN
                } else {
                    let mut max_raw = i64::MIN;
                    for &raw in self.reading.temperatures_raw.iter() {
                        max_raw = max_raw.max(raw as i64);
                    }
                    (max_raw as f32 - 2731.0) / 10.0
                }
            }
            fn run_time(&self) -> f32 { f32::NAN }
            type StorageCellsItem<'b> = StorageCellCdrView<'b> where Self: 'b;
            fn storage_cells(&self) -> impl Iterator<Item = Self::StorageCellsItem<'_>> + '_ {
                self.reading
                    .cell_voltages_mv
                    .iter()
                    .enumerate()
                    .map(move |(i, _)| StorageCellCdrView { index: i, reading: self.reading })
            }
        }

        /// `PowerHardwareUpdate` battery view (energy_storage only).
        pub struct PowerHardwareUpdateCdrView<'a> {
            pub reading: &'a CanonicalReading,
            pub device_id: &'a Identity,
            pub now: &'a ClockMonotonic,
        }
        impl<'a> lib_tms::generated_cdr::power_hardware_update_cdr::PowerHardwareUpdateCdrSrc
            for PowerHardwareUpdateCdrView<'a>
        {
            fn device_id(&self) -> &str { self.device_id.as_str() }
            type Timestamp<'b> = &'b ClockMonotonic where Self: 'b;
            fn timestamp(&self) -> Self::Timestamp<'_> { self.now }
            type Engine<'b> = Absent where Self: 'b;
            fn engine(&self) -> Option<Self::Engine<'_>> { None }
            type Fuel<'b> = Absent where Self: 'b;
            fn fuel(&self) -> Option<Self::Fuel<'_>> { None }
            type Generator<'b> = Absent where Self: 'b;
            fn generator(&self) -> Option<Self::Generator<'_>> { None }
            type EnergyStorage<'b> = EnergyStorageCdrView<'b> where Self: 'b;
            fn energy_storage(&self) -> Option<Self::EnergyStorage<'_>> {
                Some(EnergyStorageCdrView { reading: self.reading })
            }
            type PowerElectronics<'b> = Absent where Self: 'b;
            fn power_electronics(&self) -> Option<Self::PowerElectronics<'_>> { None }
            type Thermal<'b> = Absent where Self: 'b;
            fn thermal(&self) -> Option<Self::Thermal<'_>> { None }
        }
    }
}

fn cdr_enc_active_diagnostic(max_dtc_lit: Literal) -> TokenStream {
    quote! {
        /// One DTC's CDR view.
        pub struct DiagnosticTroubleCodeCdrView<'a> {
            pub spn: u32,
            pub hint: &'a str,
            pub now: &'a ClockMonotonic,
            pub occurrence_count: u32,
        }
        impl<'a> lib_tms::generated_cdr::diagnostic_trouble_code_cdr::DiagnosticTroubleCodeCdrSrc
            for DiagnosticTroubleCodeCdrView<'a>
        {
            fn port_number(&self) -> Option<i32> { None }
            fn suspect_parameter(&self) -> u32 { self.spn }
            fn failure_mode(&self) -> lib_tms::generated::FailureModeIndicator {
                lib_tms::generated::FailureModeIndicator::ConditionExists
            }
            fn occurrence_count(&self) -> u32 { self.occurrence_count }
            type TimeRaised<'b> = &'b ClockMonotonic where Self: 'b;
            fn time_raised(&self) -> Self::TimeRaised<'_> { self.now }
            fn severity(&self) -> lib_tms::generated::DtcSeverity {
                lib_tms::generated::DtcSeverity::Major
            }
            type EstimateTime<'b> = &'b ClockMonotonic where Self: 'b;
            fn estimate_time(&self) -> Option<Self::EstimateTime<'_>> { None }
            fn estimate_severity(&self) -> Option<lib_tms::generated::DtcSeverity> { None }
            fn hint(&self) -> &str { self.hint }
        }

        /// `ActiveDiagnosticState` battery view.
        pub struct ActiveDiagnosticStateCdrView<'a> {
            pub fault: &'a CanonicalFault,
            pub device_id: &'a Identity,
            pub now: &'a ClockMonotonic,
        }
        impl<'a> lib_tms::generated_cdr::active_diagnostic_state_cdr::ActiveDiagnosticStateCdrSrc
            for ActiveDiagnosticStateCdrView<'a>
        {
            fn device_id(&self) -> &str { self.device_id.as_str() }
            type CodesItem<'b> = DiagnosticTroubleCodeCdrView<'b> where Self: 'b;
            fn codes(&self) -> impl Iterator<Item = Self::CodesItem<'_>> + '_ {
                let mut emitted = 0usize;
                let fault = self.fault;
                let now = self.now;
                FAULT_TABLE.iter().filter_map(move |&(is_set, spn, hint)| {
                    if !is_set(fault) { return None; }
                    if emitted >= #max_dtc_lit { return None; }
                    emitted += 1;
                    Some(DiagnosticTroubleCodeCdrView { spn, hint, now, occurrence_count: 1 })
                })
            }
            fn overflow(&self) -> u32 {
                let mut overflow = 0u32;
                let fault = self.fault;
                let mut emitted = 0usize;
                for &(is_set, _, _) in FAULT_TABLE {
                    if is_set(fault) {
                        if emitted >= #max_dtc_lit { overflow += 1; } else { emitted += 1; }
                    }
                }
                overflow
            }
        }
    }
}
